let app = Router::new()
    .route("/orders/:id", get(get_order))
    .layer(middleware::from_fn(|mut req: Request, next: Next| async move {
        let user = authenticate(&req).map_err(|_| StatusCode::UNAUTHORIZED)?;
        authorize(&user, req.uri()).map_err(|_| StatusCode::FORBIDDEN)?;
        req.extensions_mut().insert(user.clone());
        audit(&user, req.uri());
        Ok::<_, StatusCode>(next.run(req).await)
    }));
